	if _effort_claim_expedition_generation[row] != expedition_ref.y:
		return out.refuse(String(REFUSE_EFFORT_CLAIM_STALE))
	return out.succeed(row)


func effort_claim_habitat_ref_of(row: int) -> Vector2i:
